CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('consumer','seller','farmer','investor','administrator') NOT NULL DEFAULT 'consumer',status ENUM('active','suspended') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE farmer_profiles (user_id BIGINT UNSIGNED PRIMARY KEY, farm_name VARCHAR(150) NOT NULL, village VARCHAR(150), district VARCHAR(100), bio TEXT, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE seller_profiles (user_id BIGINT UNSIGNED PRIMARY KEY, business_name VARCHAR(150) NOT NULL, phone VARCHAR(30), address TEXT, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,seller_id BIGINT UNSIGNED NOT NULL,name_en VARCHAR(150) NOT NULL,name_ta VARCHAR(150) NOT NULL,description_en TEXT,description_ta TEXT,category ENUM('vegetable','fruit') NOT NULL,price DECIMAL(10,2) NOT NULL,unit VARCHAR(20) NOT NULL,status ENUM('draft','active','archived') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(seller_id) REFERENCES users(id),INDEX(category,status));
CREATE TABLE inventory (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL UNIQUE,quantity_available INT NOT NULL DEFAULT 0,reorder_level INT NOT NULL DEFAULT 5,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE baskets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,status ENUM('active','converted','abandoned') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(id));
CREATE TABLE basket_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,basket_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,UNIQUE(basket_id,product_id),FOREIGN KEY(basket_id) REFERENCES baskets(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,basket_id BIGINT UNSIGNED,payment_status ENUM('pending','paid','refunded') DEFAULT 'pending',fulfilment_status ENUM('placed','confirmed','packed','shipped','delivered','cancelled') DEFAULT 'placed',total_amount DECIMAL(12,2) NOT NULL,delivery_address TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(basket_id) REFERENCES baskets(id));
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,seller_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,fulfilment_status ENUM('placed','packed','shipped','delivered','cancelled') DEFAULT 'placed',FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(seller_id) REFERENCES users(id));
CREATE TABLE investment_campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,farmer_id BIGINT UNSIGNED NOT NULL,title_en VARCHAR(200) NOT NULL,title_ta VARCHAR(200) NOT NULL,description_en TEXT,description_ta TEXT,target_amount DECIMAL(12,2) NOT NULL,minimum_investment DECIMAL(10,2) NOT NULL,opens_at DATETIME NOT NULL,closes_at DATETIME NOT NULL,status ENUM('draft','funding','funded','harvested','closed') DEFAULT 'draft',harvest_outcome TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(farmer_id) REFERENCES users(id));
CREATE TABLE investments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,investor_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(12,2) NOT NULL,status ENUM('pending','confirmed','refunded') DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(campaign_id) REFERENCES investment_campaigns(id),FOREIGN KEY(investor_id) REFERENCES users(id));
CREATE TABLE profit_distributions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,campaign_id BIGINT UNSIGNED NOT NULL,investment_id BIGINT UNSIGNED NOT NULL,profit_amount DECIMAL(12,2) NOT NULL,status ENUM('planned','paid') DEFAULT 'planned',paid_at DATETIME,FOREIGN KEY(campaign_id) REFERENCES investment_campaigns(id),FOREIGN KEY(investment_id) REFERENCES investments(id));
CREATE TABLE transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,entity_type VARCHAR(50) NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(50) NOT NULL,amount DECIMAL(12,2),reference VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX(entity_type,entity_id));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED,action VARCHAR(100) NOT NULL,entity_type VARCHAR(50) NOT NULL,entity_id BIGINT UNSIGNED,metadata JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_id) REFERENCES users(id),INDEX(entity_type,entity_id));
